26: function tick(){if(!S.playing)return;const r=new RNG(hashSeed(S.seed+':'+S.tick));S.tick++;let e=S.env,stress=environmentStress(e);let expressions=traitMap(S.genome,e),metabolic=expressions['ATP synthase']||.5,repair=expressions['DNA ligase']||.5,transport=expressions['Membrane transporter']||.5;S.atp=clamp(S.atp+.045*metabolic*e.oxygen+.025*e.nutrients-.035-stress*.018,.3,7);S.damage=clamp(S.damage+stress*.16-repair*.1+r.normal()*.12,0,100);S.viability=clamp(S.viability+.025*(S.atp-2.7)-stress*.17-S.damage*.001+r.normal()*.07,0,100);S.senescence=clamp(S.senescence+.007+stress*.012,0,100);let growth=(S.viability/100)*(.35+transport*.45)*e.nutrients;if(r.next()<.32)S.population=clamp(Math.round(S.population+growth*2-r.next()*1.7),15,6000);S.cellCount=Math.round(S.population*12+S.viability*8);S.liveCells=Math.round(S.cellCount*S.viability/100);S.fitness=clamp(.25+S.viability*.005+metabolic*.13+transport*.08-stress*.13,0,1);if(S.tick%16===0)e.nutrients=clamp(e.nutrients-.015+r.next()*.026,.1,1);if(S.tick%25===0)generationStep();if(S.tick%4===0){storeState();if(currentView==='overview'||currentView==='evolution')render()}}
27: function generationStep(){let old=S.genome, rng=new RNG(hashSeed(S.seed+':generation:'+S.generation)),child=makeGenome(`${S.seed}:${S.generation+1}`,old);child.generation=S.generation+1;child.mutations=old.mutations;let mutationRate=.001+(S.env.radiation*.008)+(S.damage/100*.002);for(const g of child.genes){if(rng.next()<mutationRate){g.mutation={from:g.coding[rng.int(g.coding.length)],position:rng.int(g.coding.length)};let pos=g.mutation.position,base=g.coding[pos];g.coding=g.coding.slice(0,pos)+rng.pick('ATCG'.replace(base,''))+g.coding.slice(pos+1);g.activity=clamp(g.activity+rng.normal()*.08,.05,1);child.mutations++;}}
