function cellView(){if(!S.plate?.length)Object.assign(S,makePlateState(S.genome,S.seed,S.viability,S.atp,0));let selected=S.plate.find(c=>c.id===S.selectedCellId)||S.plate[0],genome=plateGenome(selected),traits=traitMap(genome,S.env),atpExpression=traits['ATP synthase']||.5,stage=cycleStage(selected.cycleProgress||0),checkpoint=cycleCheckpoint(selected),organelles=[['Cell membrane',`${f(selected.membrane,1)}% integrity · transport boundary`],['Cytoplasm',`${f(atpExpression*100,0)}% metabolic activity`],['Nucleus',`${genome.genes.length} annotated loci · ${genome.id}`],['Mitochondria',`${f(selected.atp,2)} mmol/L ATP proxy · ROS ${f(selected.ros,1)}`],['Ribosomes',`${genome.genes.length} active transcript targets`],['Endoplasmic reticulum',`${f((traits['Heat-shock protein']||.5)*100,0)}% folding response · load ${f(selected.proteinLoad,1)}%`],['Golgi apparatus','Protein processing'],['Lysosomes','Turnover · autophagy proxy'],['Cytoskeleton',`${selected.archived?'archived':'live'} lineage · generation ${selected.generation}`],['Cell receptors',`${f((S.env.nutrients+.2)*7,1)} relative signal capacity`]];return `${pageHead(`LIVE IMAGING · CELL ${String(S.tick%9999).padStart(4,'0')}`,'Cell observatory','Every pulse reflects the selected cell’s genome and measured state.',`<button class="subtle-button" data-action="plate-live">＋ Add live cells</button><button class="subtle-button" data-action="cell-cycle">↻ Advance cell cycle</button><button class="subtle-button" data-action="stain">◉ Stain selected</button>`)}<section class="card plate-card"><div class="card-head"><div><span class="card-title">Observatory plate <span class="card-meta">/ CULTURE DISH · ${S.plate.length} OF 30 CELLS</span></span><div class="plate-caption">Select any cell to inspect it. Pulse rate and hue are derived from its expressed genome.</div></div><span class="tag green">${S.plate.length} ON PLATE</span></div><div class="plate-stage"><div class="plate-dish"><div class="plate-rim"></div><div class="plate-well"></div>${S.plate.map(plateCellMarkup).join('')}<span class="plate-crosshair h"></span><span class="plate-crosshair v"></span></div><div class="plate-overlay"><span>FIELD 01</span><span>${S.playing?'MOTION ACTIVE':'MOTION CONTINUES'}</span></div></div><div class="plate-summary"><span>MEAN VIABILITY <b>${f(S.plate.reduce((n,c)=>n+c.viability,0)/S.plate.length,1)}%</b></span><span>STAINED <b>${S.plate.filter(c=>c.stained).length}</b></span><span>MEAN DAMAGE <b>${f(S.plate.reduce((n,c)=>n+(c.damage||0),0)/S.plate.length,1)}%</b></span><span>MEAN ROS <b>${f(S.plate.reduce((n,c)=>n+(c.ros||0),0)/S.plate.length,1)}%</b></span><span>CHECKPOINT BLOCKED <b>${S.plate.filter(c=>cycleCheckpoint(c)!=='PASS').length}</b></span><span>CAPACITY <b>${30-S.plate.length} OPEN</b></span></div><div class="plate-footer"><div class="plate-legend"><span><i class="plate-legend-dot"></i>LIVE CULTURE</span><span><i class="plate-legend-dot archive"></i>ARCHIVED LINEAGE</span><span><i class="plate-legend-dot selected"></i>SELECTED</span></div><div class="plate-load"><select id="plate-archive" aria-label="Choose archived cell"><option value="">Load archived cell…</option>${(S.archive||[]).map((g,i)=>`<option value="${i}">${g.id} · generation ${g.generation}</option>`).join('')}</select><button class="tiny-control" data-action="plate-archive">LOAD TO PLATE</button></div></div></section><div class="cell-layout plate-details"><section class="card"><div class="card-head"><span class="card-title">Selected cell · ${selected.id}</span><span class="tag ${selected.archived?'':'green'}">${selected.sourceLabel}</span></div><div class="selected-lineage"><strong>${genome.id}</strong><span>${genome.species||'Pelagomyces isolate'} · generation ${selected.generation}</span></div><div class="cell-reading"><span>VIABILITY</span><b>${f(selected.viability,1)} %</b></div><div class="cell-reading"><span>ATP · MODEL PROXY</span><b>${f(selected.atp,2)} mmol/L</b></div><div class="cell-reading"><span>DAMAGE · MODEL PROXY</span><b>${f(selected.damage||0,1)} %</b></div><div class="cell-reading"><span>OXIDATIVE STRESS · ROS</span><b>${f(selected.ros||0,1)} %</b></div><div class="cell-reading"><span>PROTEIN-FOLDING LOAD</span><b>${f(selected.proteinLoad||0,1)} %</b></div><div class="cell-reading"><span>MEMBRANE INTEGRITY</span><b>${f(selected.membrane??100,1)} %</b></div><div class="cell-reading"><span>CELL STATE</span><b class="state-${selected.state}">${selected.state.toUpperCase()}</b></div><div class="cell-reading"><span>CYCLE STAGE</span><b>${stage} · ${f((selected.cycleProgress||0)*100,0)} %</b></div><div class="cell-reading"><span>DIVISION CHECKPOINT</span><b class="checkpoint-${checkpoint==='PASS'?'pass':'blocked'}">${checkpoint}</b></div><div class="cell-reading"><span>AGE · SIMULATION TICKS</span><b>${(selected.age||0).toLocaleString()}</b></div><div class="cell-reading"><span>DIVISIONS</span><b>${selected.divisions||0}</b></div><div class="cell-reading"><span>DOMINANT EXPRESSION</span><b>${Object.entries(traits).sort((a,b)=>b[1]-a[1])[0]?.[0]||'—'}</b></div><div class="cell-reading"><span>GENOME GC CONTENT</span><b>${f(gc(genome.sequence),1)} %</b></div><button class="action-button primary inspect-action" data-action="inspect-genome">⌁ &nbsp; Inspect this genome</button><button class="subtle-button inspect-action" data-action="remove-cell">× Remove selected cell from plate</button></section><section class="card"><div class="card-head"><span class="card-title">Organelle registry</span><span class="card-meta">SELECTED CELL · RELATIVE</span></div><div class="organelle-list">${organelles.map(o=>`<div class="organelle-row"><span>${o[0]}</span><small>${o[1]}</small></div>`).join('')}</div><div class="disclaimer">Cell motion is a schematic model. ATP, viability and gene-expression values are educational proxies, not biological predictions.</div></section></div>`}
const PROTOCOLS=[['DNA extraction','⌁','Lyse sampled cells and isolate nucleic acid.','SAMPLE REQUIRED · 15 MIN'],['RNA extraction','∿','Recover RNA; degradation can reduce yield.','SAMPLE REQUIRED · 12 MIN'],['PCR amplification','⤴','Amplify a selected locus from extracted DNA.','DNA EXTRACT · 2 H'],['Gel electrophoresis','▥','Separate fragments by approximate length.','PCR PRODUCT · 45 MIN'],['Sanger sequencing','↠','Read a short amplicon with terminal-variation limits.','PCR PRODUCT · 3 H'],['Whole-genome sequencing','⌘','Estimate full simulated reference and variant calls.','DNA EXTRACT · 8 H'],['Gene expression assay','≋','Measure expression from model transcript abundance.','RNA EXTRACT · 1 H'],['Protein analysis','◈','Infer translated peptide profile and relative abundance.','CELL LYSATE · 2 H'],['Cell viability','◉','Estimate viable fraction using a virtual dye-exclusion count.','LIVE CULTURE · 10 MIN'],['Karyotype','▤','Inspect chromosome count and large-scale abnormalities.','CELL CULTURE · 4 H'],['CRISPR edit simulation','✳','Model a targeted sequence edit; outcomes are simplified.','DESIGN + DNA · 1 DAY'],['Comparative genomics','⇄','Compare this genome with archived lineages.','2 ASSEMBLIES · 20 MIN']];
function resultMarkup(){let r=S.labResults[0];if(!r)return '<div class="result-empty">Select a protocol to configure and run a traceable experiment.<br><br><span class="tag">RESULTS WILL REFERENCE THE ACTIVE GENOME</span></div>';return `<div class="result-title"><div><strong>${r.protocol}</strong><div class="card-meta" style="margin-top:5px">${r.id} · ${r.date} · ${r.genome}</div></div><span class="tag green">COMPLETE</span></div><div class="result-data">${r.values.map(v=>`<div class="result-cell"><span>${v[0]}</span><strong>${v[1]}</strong></div>`).join('')}</div><p style="font-size:10px;color:#8e9b91;line-height:1.55;margin:13px 0 0">${r.note}</p>`}
function labView(){let req=activeProtocol==='DNA extraction'?'Ready for extraction':S.samples.dna?'DNA extract available':'Sample available · extract DNA first';return `${pageHead(`EXPERIMENTAL SUITE · PROTOCOL ${String(S.experimentCount+1).padStart(3,'0')}`,'Wet lab','Run simplified, traceable procedures against your organism’s actual genome.',`<span class="tag ${S.samples.dna?'green':''}">${req.toUpperCase()}</span>`)}<div class="section-grid"><section class="card"><div class="card-head"><span class="card-title">Protocol library</span><span class="card-meta">12 METHODS · MODELLED</span></div><div class="protocol-grid">${PROTOCOLS.map(p=>`<button class="protocol-option ${activeProtocol===p[0]?'selected':''}" data-protocol="${p[0]}"><div class="protocol-icon">${p[1]}</div><strong>${p[0]}</strong><p>${p[2]}</p><small>${p[3]}</small></button>`).join('')}</div></section><div style="display:grid;gap:14px;align-content:start"><section class="card"><div class="card-head"><span class="card-title">Bench configuration</span><span class="card-meta">${activeProtocol.toUpperCase()}</span></div><div class="gene-detail"><div class="mini-stat"><span>SUBJECT / REFERENCE</span><strong>${S.genome.id}<small> · generation ${S.generation}</small></strong></div><label class="modal-label" style="display:block;font:9px var(--mono);color:#829188;margin:17px 0 6px">TARGET LOCUS</label><select class="select-button" id="target-gene" style="width:100%">${S.genome.genes.map(g=>`<option value="${g.id}">${g.id} · ${g.name}</option>`).join('')}<option value="whole">Whole genome</option></select><div class="chip-row"><span class="chip">SAMPLE ${S.samples.dna?'DNA EXTRACTED':'LIVE CULTURE'}</span><span class="chip">REPLICATE n=1</span></div><button class="action-button primary" style="width:100%;margin-top:6px" data-action="run-lab">▶ &nbsp; Run ${activeProtocol}</button></div></section><section class="card"><div class="card-head"><span class="card-title">Latest result</span><span class="card-meta">${S.labResults.length} EXPERIMENTS</span></div><div class="lab-result">${resultMarkup()}</div></section><div class="disclaimer">Educational simulation only. Protocol outputs are deterministic estimates from this model, not clinical or laboratory instructions. No wet-lab procedure is being performed.</div></div></div>`}
