 function newWorld(source){S=initialState(`GEN-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`,source);S.archive=loadState()?.archive||[];S.notebook=[];S.playing=false;storeState();currentView='overview';render();toast(source?`New world seeded from ${source.id}`:'A new biological history has begun.')}
